SourceCode.Declaration:
internal class GUPPriceEngineMarginCodeLineAggregation extends GUPPriceEngineAbstractLineAggregation
{
    // List<GUPPriceEngineDecoratedAdjustmentValueLine> contains GUPPriceEngineMarginCodeLine.
    // Stores all compete lines with Calculate Method = 'Percent'.
    List percentLineList;
    // 5.5 denotes 5.5%. Can be negative.
    real lowestPercentage = realMax();
    // Length of percentLineList
    int percentListLength = 0;

    // List<GUPPriceEngineDecoratedAdjustmentValueLine> contains GUPPriceEngineMarginCodeLine.
    // Stores all compete lines with Calculate Method = 'Fixed Amount'.
    List fixedAmountlineList;
    // Must be with same currency. Can be negative.
    real lowestAmount = realMax();
    // Length of fixedAmountlineList
    int fixedAmountListLength = 0;

    real computedPrice = 0;
    boolean isComputed = false;

}

Method.Source:
    public real parmComputedPrice(real _computedPrice = 0)
    {
        if (_computedPrice)
        {
            this.computedPrice = _computedPrice;
        }

        return this.computedPrice;
    }

    public boolean parmIsComputed(boolean _isComputed = false)
    {
        if (_isComputed)
        {
            this.isComputed = _isComputed;
        }

        return this.isComputed;
    }

    public void addCompeteLine(GUPPriceEngineMarginCodeLine _line, int _linePriority)
    {
        if(this.attributeGroupKey != null && this.attributeGroupKey != _line.parmAttributeGroupKey())
        {
            Error("Lines in aggregation must have same attribute group key.");
        }

        this.attributeGroupKey = _line.parmAttributeGroupKey();
        this.linePriority = _linePriority;
        lineRecIdSet.add(_line.parmJournalLineRecId());
        
        GUPPriceTermCalculateMethod method = _line.parmComponentLine().CalculateMethod;
        real adjustmentValue = _line.parmComponentLine().DiscountPercentOrValue;
        
        GUPPriceEngineDecoratedAdjustmentValueLine decoratedLine =
            GUPPriceEngineDecoratedAdjustmentValueLine::newInstanceByAdjustmentValueAndLine(adjustmentValue, _line);

        if (method == GUPPriceTermCalculateMethod::Percent)
        {
            if (!percentLineList)
            {
                percentLineList = new List(Types::AnyType);
            }
            percentLineList.addEnd(decoratedLine);
            percentListLength ++;

            if (adjustmentValue < this.lowestPercentage)
            {
                this.lowestPercentage = adjustmentValue;
            }
        }
        else 
        {
            if (!fixedAmountlineList)
            {
                fixedAmountlineList = new List(Types::AnyType);
            }
            fixedAmountlineList.addEnd(decoratedLine);
            fixedAmountListLength ++;

            if (adjustmentValue < this.lowestAmount)
            {
                this.lowestAmount = adjustmentValue;
            }
        }
    }

    public void sortLineList()
    {
        GUPListSorter listSorter = GUPListSorter::getInstance();
        GUPComparatorDecoratedAdjustmentValueLine lineComparator = new GUPComparatorDecoratedAdjustmentValueLine();

        if (percentListLength > 1)
        {
            this.percentLineList = listSorter.sortList(this.percentLineList, lineComparator);
        }

        if (fixedAmountListLength > 1)
        {
            this.fixedAmountlineList = listSorter.sortList(this.fixedAmountlineList, lineComparator);
        }
    }

    /// <summary>
    /// Used when attributeGroupKey is same, to avoid hash collision.
    /// </summary>
    /// <param name = "_newLine">Another line to compare.</param>
    /// <returns>True if two lines are compete.</returns>
    public boolean canAddAsCompeteLine(GUPPriceEngineAbstractLine _newLine)
    {
        if (percentListLength == 0 && fixedAmountListLength == 0)
        {
            return true;
        }

        List existList = (percentListLength == 0) ? fixedAmountlineList : percentLineList;

        ListEnumerator enumerator = existList.getEnumerator();
        enumerator.moveNext();
        return _newLine.isCompeteLine(enumerator.current());
    }
